package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type TempRec struct { // 01 TEMP-REC, 8 bytes
	TcSensor string          // PIC X(4) @0 len=4
	TcF      decimal.Decimal // PIC 9(3)V9 @4 len=4
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string         // PIC X len=1 = "N"
var WsC decimal.Decimal      // PIC S9(3)V99 len=5 = 0
var WsFreeze int64           // PIC 99 len=2 = 0
var WsCount int64            // PIC 99 len=2 = 0
var WsFEd string             // PIC ZZ9.9 len=5
var WsCEd string             // PIC -ZZ9.99 len=7

var tempRec TempRec

var inputLines []string
var inputIndex int

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

// helpers for numeric-edited formatting

func formatEdited(absVal decimal.Decimal, intDigits int, fracDigits int, picInt string) string {
	// absVal is non-negative
	pow10int := int64(1)
	for i := 0; i < intDigits; i++ {
		pow10int *= 10
	}
	powFrac := int64(1)
	for i := 0; i < fracDigits; i++ {
		powFrac *= 10
	}

	// integer part with high-order truncation
	intPart := absVal.IntPart() // trunc toward zero, for positive it's floor
	if intPart < 0 {
		intPart = -intPart
	}
	// handle overflow: keep low-order digits
	if pow10int > 0 {
		intPart = intPart % pow10int
	}

	// integer string zero-padded
	intStr := fmt.Sprintf("%0*d", intDigits, intPart)

	// Z suppression
	suppressed := true
	runes := []rune(intStr)
	for i := 0; i < intDigits; i++ {
		if suppressed && picInt[i] == 'Z' && runes[i] == '0' {
			// need to check if there is any non-zero later before leaving suppressed?
			// COBOL replaces leading zeros in Z positions with spaces as long as no
			// non-zero has been encountered yet.
			runes[i] = ' '
		} else {
			// once we encounter a non-zero digit, or a '9' position, stop suppression
			if runes[i] != '0' || picInt[i] == '9' {
				// if digit is non-zero, suppression ends; if digit is zero but picture is 9, we keep zero and end
				// For zero digits in Z positions that follow suppression end (should not happen because we broke earlier),
				// they stay as '0'. The loop below will handle remaining chars.
				suppressed = false
				// Need to mark end of suppression; subsequent Z positions that are '0' should stay '0'
				// So break the special handling
				// We must not re-evaluate earlier positions
				// For remaining positions, just keep as is
				// But we need to continue to not convert further Z zeros to spaces
				// So we need to track that we've left suppressed zone
				// Implement by setting suppressed=false and continuing without conversion
			} else {
				// This case is Z with '0' but we have already decided? Actually if suppressed still true and digit is 0,
				// we already handled above. So this branch is for Z with 0 where we want to keep? No.
				suppressed = false
			}
			// After suppression ends, remaining digits stay as they are
			// Break out of suppression logic: just keep runes as is
			// To avoid converting further Z's, we set a flag and skip conversion
			// We'll continue loop with no conversion
			// Use a separate flag
			break
		}
	}
	// The above break-style loop is flawed for cases like "005" -> we replaced index0 with space,
	// then at index1 we still suppressed and digit '0', should replace with space, not break.
	// Redo properly with simple loop:
	// Recompute correctly:
	intStr2 := fmt.Sprintf("%0*d", intDigits, intPart)
	runes2 := []rune(intStr2)
	suppress := true
	for i := 0; i < intDigits; i++ {
		if suppress && picInt[i] == 'Z' && runes2[i] == '0' {
			runes2[i] = ' '
		} else {
			suppress = false
		}
	}
	intFormatted := string(runes2)

	// fractional part
	fracStr := ""
	if fracDigits > 0 {
		shifted := absVal.Shift(int32(fracDigits)).Truncate(0)
		// shifted is absVal * 10^fracDigits truncated
		// For negative values absVal already positive, so fine
		si := shifted.IntPart()
		if si < 0 {
			si = -si
		}
		fracPart := si % powFrac
		fracStr = fmt.Sprintf("%0*d", fracDigits, fracPart)
		return intFormatted + "." + fracStr
	}
	return intFormatted
}

func formatZZ9_9(d decimal.Decimal) string {
	absVal := d.Abs()
	// TC-F scale 1, picture scale 1 -> no extra rounding needed
	return formatEdited(absVal, 3, 1, "ZZ9")
}

func formatMinusZZ9_99(d decimal.Decimal) string {
	sign := ' '
	if d.Sign() < 0 {
		sign = '-'
	}
	absVal := d.Abs()
	edited := formatEdited(absVal, 3, 2, "ZZ9")
	return string(sign) + edited
}

