	}
	return s
}

// paragraph functions

func ReadPara() {
	if inputIndex >= len(inputLines) {
		WsEofFlag = "Y"
		return
	}
	line := inputLines[inputIndex]
	inputIndex++
	// line already padded to 8
	// parse
	tcSensor := line[0:4]
	tcFStr := line[4:8]
	// parse TC-F : 4 digits, implied 1 decimal
	// keep digits only
	digits := ""
	for _, ch := range tcFStr {
		if ch >= '0' && ch <= '9' {
			digits += string(ch)
		} else if ch == ' ' {
			// space treated as 0? but ignore
		}
	}
	var tcF decimal.Decimal
	if digits == "" {
		tcF = decimal.NewFromInt(0)
	} else {
		// digits as integer, scale -1
		var n int64
		fmt.Sscanf(digits, "%d", &n)
		// digits may have leading zeros, Sscanf ok
		// Use decimal.New(n, -1)
		tcF = decimal.New(n, -1)
	}
	tempRec.TcSensor = tcSensor
	tempRec.TcF = tcF
}

func ProcessPara() {
	// COMPUTE WS-C ROUNDED = (TC-F - 32) * 5 / 9
	tmp := tempRec.TcF.Sub(decimal.NewFromInt(32)).Mul(decimal.NewFromInt(5)).Div(decimal.NewFromInt(9))
	WsC = tmp.Round(2)
	// store overflow truncation for S9(3)V99 (3 int digits scale2) – not needed for given range but implement
	// Truncate high-order: keep low-order digits
	// For completeness, apply modulo 1000 on integer part
	// We already have rounded value within range, so skip

	if WsC.Sign() < 0 {
		WsFreeze++
	}
	WsCount++
	WsFEd = formatZZ9_9(tempRec.TcF)
	WsCEd = formatMinusZZ9_99(WsC)
	// DISPLAY TC-SENSOR " " WS-F-ED "F " WS-C-ED "C"
	// TC-SENSOR is X(4) exactly 4 chars
	fmt.Printf("%s %sF %sC\n", tempRec.TcSensor, WsFEd, WsCEd)
	ReadPara()
}

func MainPara() {
	// OPEN INPUT TEMP-FILE
	f, err := os.Open("input.dat")
	if err != nil {
		fmt.Fprintf(os.Stderr, "open input.dat: %v\n", err)
		os.Exit(1)
	}
	defer f.Close()
	scanner := bufio.NewScanner(f)
	// Increase buffer for long lines (though record is 8)
	buf := make([]byte, 0, 64*1024)
	scanner.Buffer(buf, 1024*1024)
	inputLines = []string{}
	for scanner.Scan() {
		line := scanner.Text()
		// COBOL LINE SEQUENTIAL: one record per line. If shorter than record length, pad with spaces on right.
		line = padRight(line, 8)
		if len(line) > 8 {
			line = line[:8]
		}
		inputLines = append(inputLines, line)
	}
	if err := scanner.Err(); err != nil {
		fmt.Fprintf(os.Stderr, "read input.dat: %v\n", err)
		os.Exit(1)
	}
	WsEofFlag = "N"
	inputIndex = 0
	ReadPara()
	for WsEofFlag != "Y" {
		ProcessPara()
	}
	// CLOSE TEMP-FILE already deferred
	// DISPLAY "READINGS: " WS-COUNT " BELOW ZERO: " WS-FREEZE
	fmt.Printf("READINGS: %s BELOW ZERO: %s\n", formatPIC99(WsCount), formatPIC99(WsFreeze))
}

func main() {
	// initialize working-storage defaults
	WsEofFlag = "N"
	WsC = decimal.NewFromInt(0)
	WsFreeze = 0
	WsCount = 0
	WsFEd = ""
	WsCEd = ""
	MainPara()
}
